// Generated by app/scripts/strip-glyphs.ts from Roboto Bold and Lucide icons.
// Don't edit it: change the script and run pnpm strip:glyphs from app/.
#pragma once

#include <stdint.h>

// Roboto Bold and the strip's icons as 1-bit pixels: each row is padded to whole
// bytes, with the most significant bit on the left.
namespace StripGlyphs
{
    struct Glyph
    {
        // Latin-1, so the degree sign is 0xB0.
        uint8_t code;
        uint8_t width;
        uint8_t height;
        // From the pen to the first column, and from the baseline to the first
        // row (negative above it), in pixels.
        int8_t left;
        int8_t top;
        // How far the pen moves afterwards, in 1/16 px.
        uint16_t advance;
        // Where its rows start in the font's bits.
        uint16_t offset;
    };

    // Added to the first character's advance when the second follows it.
    struct Kerning
    {
        uint8_t first;
        uint8_t second;
        // In 1/16 px.
        int16_t adjust;
    };

    struct Font
    {
        uint8_t size;
        // The height of a capital letter, in pixels.
        uint8_t capHeight;
        uint8_t glyphCount;
        const Glyph* glyphs;
        const uint8_t* bits;
        uint8_t kerningCount;
        const Kerning* kerning;
    };

    struct Icon
    {
        uint8_t width;
        uint8_t height;
        const uint8_t* bits;
    };

    extern const Font batteryFont; // 16px, the percentage in a low battery
    extern const Font rowFont; // 40px, the top row
    extern const Font barFont; // 64px, the litres in the bar

    extern const Icon brain; // Smart mode
    extern const Icon leaf; // Eco (Ultra Low Power) mode
    extern const Icon warning; // the laser is in the other mode
    extern const Icon noSignal; // nothing heard from the laser
}
